// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        bool ok;
        // call transfer, catch revert
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = true;
            assertTrue(ret == (2 == 2));
        } catch {
            ok = false;
            assertTrue(true); // if reverts, property vacuously holds
        }
        // additional constraint that the test only passes if transfer completes (to focus on return value difference)
        // but the assertion above already covers both cases.
    }
}

